// On-demand SRT -> WebVTT export (PLAN-012). The bilingual .srt remains the
// canonical transcript artifact (ADR-007); the .vtt is a derived view built
// per request and never persisted. Pure conversion: no I/O, no imports.

// VTT cue text escapes &, <, >. Escaping > also neutralizes a literal `-->`
// inside text (becomes `--&gt;`), which raw VTT cue text forbids.
function escapeVttText(line: string): string {
  return line
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;');
}

function blockToCue(block: string): string {
  const lines = block.split('\n');
  const out: string[] = [];
  let i = 0;
  // When the first line is not the timing line it is a cue identifier kept
  // verbatim (SRT cue numbers are valid VTT cue identifiers).
  if (!lines[0]?.includes(' --> ')) {
    out.push(lines[0]!);
    i = 1;
  }
  // Timing line: verbatim except the SRT `HH:MM:SS,mmm` comma becomes a dot.
  const timing = lines[i];
  if (timing !== undefined) out.push(timing.replace(/,/g, '.'));
  for (const line of lines.slice(i + 1)) {
    out.push(escapeVttText(line));
  }
  return out.join('\n');
}

export function srtToVtt(srt: string): string {
  const blocks = srt.split(/\n{2,}/).filter((b) => b.trim() !== '');
  if (blocks.length === 0) return 'WEBVTT\n';
  return `WEBVTT\n\n${blocks.map(blockToCue).join('\n\n')}\n`;
}

import { describe, expect, it } from 'vitest';
import { srtToVtt } from './vtt.js';

describe('srtToVtt', () => {
  it('converts a single bilingual cue', () => {
    const srt =
      '1\n00:00:02,000 --> 00:00:04,800\nSpeaker 1: Hello.\nXin chào.\n\n';
    expect(srtToVtt(srt)).toBe(
      'WEBVTT\n\n' +
        '1\n00:00:02.000 --> 00:00:04.800\nSpeaker 1: Hello.\nXin chào.\n',
    );
  });

  it('separates cues with one blank line and ends with a single newline', () => {
    const srt =
      '1\n00:00:01,000 --> 00:00:02,000\nHi.\n\n' +
      '2\n00:00:03,500 --> 00:00:04,000\nYo.\n\n';
    const vtt = srtToVtt(srt);
    expect(vtt).toBe(
      'WEBVTT\n\n' +
        '1\n00:00:01.000 --> 00:00:02.000\nHi.\n\n' +
        '2\n00:00:03.500 --> 00:00:04.000\nYo.\n',
    );
    expect(vtt.endsWith('\n')).toBe(true);
    expect(vtt.endsWith('\n\n')).toBe(false);
  });

  it('keeps an identifier-less cue without inventing an identifier', () => {
    expect(srtToVtt('00:00:01,000 --> 00:00:02,000\nBare text.\n')).toBe(
      'WEBVTT\n\n00:00:01.000 --> 00:00:02.000\nBare text.\n',
    );
  });

  it('escapes &, <, > and neutralizes a literal --> in cue text', () => {
    const vtt = srtToVtt(
      '1\n00:00:01,000 --> 00:00:02,000\na & b <tag> x --> y\n',
    );
    expect(vtt).toContain('a &amp; b &lt;tag&gt; x --&gt; y');
    // the header arrow on the timing line stays raw
    expect(vtt).toContain('00:00:01.000 --> 00:00:02.000');
  });

  it('emits the bare header for empty or whitespace-only input', () => {
    expect(srtToVtt('')).toBe('WEBVTT\n');
    expect(srtToVtt('   ')).toBe('WEBVTT\n');
    expect(srtToVtt('  \n\n \t\n')).toBe('WEBVTT\n');
  });

  it('rewrites comma decimals as dots, hours-padded included', () => {
    const vtt = srtToVtt('7\n01:02:03,456 --> 01:02:05,001\ntext\n');
    expect(vtt).toContain('7\n01:02:03.456 --> 01:02:05.001\ntext');
  });
});

