describe('session vtt export', () => {
  it('serves the stored .srt as a downloadable .vtt', async () => {
    const res = await app.inject({
      method: 'POST',
      url: '/api/sessions',
      payload: { diarize: true },
    });
    expect(res.statusCode).toBe(201);
    const info = res.json() as { id: string };
    provider.emitFinal({
      text: 'Hello.',
      speaker: 'Speaker 1',
      start_s: 2,
      end_s: 4.8,
    });
    // cue + translation writes are queued; wait until both have landed
    const srtPath = srtPathFor(dir, info.id);
    await vi.waitFor(async () =>
      expect(await fs.readFile(srtPath, 'utf8')).toContain('XIN CHÀO'),
    );
    await app.inject({ method: 'POST', url: `/api/sessions/${info.id}/stop` });

    const vtt = await app.inject({
      method: 'GET',
      url: `/api/sessions/${info.id}/export.vtt`,
    });
    expect(vtt.statusCode).toBe(200);
    expect(String(vtt.headers['content-type'])).toMatch(/^text\/vtt/);
    const stem = path.basename(filePathFor(dir, info.id), '.md');
    expect(vtt.headers['content-disposition']).toBe(
      `attachment; filename="${stem}.vtt"`,
    );
    expect(vtt.body.startsWith('WEBVTT\n')).toBe(true);
    expect(vtt.body).toContain('00:00:02.000 --> 00:00:04.800');
    expect(vtt.body).toContain('Speaker 1: Hello.');
    expect(vtt.body).not.toContain(',000');

    // the export is byte-faithful to whatever the .srt holds at request time
    const read = await app.inject({
      method: 'GET',
      url: `/api/sessions/${info.id}`,
    });
    const stored = read.json() as { srt: string };
    expect(vtt.body).toBe(srtToVtt(stored.srt));
  });

  it('returns 404 for an unknown session id', async () => {
    const res = await app.inject({
      method: 'GET',
      url: '/api/sessions/nope-1/export.vtt',
    });
    expect(res.statusCode).toBe(404);
    expect((res.json() as { error?: string }).error).toBe(
      'session not found: nope-1',
    );
  });
});

